import json, numpy as np, choix

DATA = "/root/causal_style_decomp_judge/data"

def all_trials_bt(filepath, pole_field="trial1_prefers_formal", nli=0.90):
    with open(filepath) as f:
        recs = [json.loads(l) for l in f]
    recs = [r for r in recs if r.get("nli_cf", 0) >= nli]
    valid = [r for r in recs if r.get("trial1_choice") and r.get("trial2_choice")]

    pole2 = pole_field.replace("trial1", "trial2")
    comps = []
    for rec in valid:
        t1 = rec.get(pole_field)
        t2 = rec.get(pole2)
        if t1 is True: comps.append((0, 1))
        elif t1 is False: comps.append((1, 0))
        if t2 is True: comps.append((0, 1))
        elif t2 is False: comps.append((1, 0))

    if len(comps) < 4:
        return None, len(valid), len(comps)
    params = choix.ilsr_pairwise(2, comps, alpha=0.01)
    bt = 1.0 / (1.0 + np.exp(-(params[0] - params[1])))
    return bt, len(valid), len(comps)

# Table T1 (Table 23) rows
configs = [
    ("AEval GPT-4o Form", f"{DATA}/pairwise_results_alpacaeval_gpt4o.jsonl", "trial1_prefers_formal", ".727"),
    ("AEval Qwen3 Form", f"{DATA}/pairwise_results_alpacaeval_qwen32b.jsonl", "trial1_prefers_formal", ".657"),
    ("AEval Qwen3 Verb", f"{DATA}/pairwise_results_alpacaeval_verbosity_qwen32b.jsonl", "trial1_prefers_verbose", ".841"),
    ("AEval Llama Form", f"{DATA}/pairwise_results_alpacaeval_llama70b_formality.jsonl", "trial1_prefers_formal", ".756"),
    ("MTB GPT-4o Form", f"{DATA}/pairwise_results_mtbench_gpt4o.jsonl", "trial1_prefers_formal", ".692"),
    ("MTB Qwen3 Form", f"{DATA}/pairwise_results_mtbench_qwen32b.jsonl", "trial1_prefers_formal", ".712"),
]

print(f"{'Config':<22} {'Table':>6} {'Computed':>9} {'n':>4} {'Match':>6}")
print("-" * 55)
for name, path, field, table_val in configs:
    try:
        bt, n, nc = all_trials_bt(path, field)
        if bt is not None:
            tv = float(table_val)
            diff = abs(bt - tv)
            match = "YES" if diff < 0.005 else f"NO({diff:.3f})"
            print(f"{name:<22} {table_val:>6} {bt:>9.4f} {n:>4} {match:>6}")
        else:
            print(f"{name:<22} {table_val:>6} {'N/A':>9} {n:>4}")
    except Exception as e:
        print(f"{name:<22} ERROR: {str(e)[:40]}")
